<script>
  // Size selection toggling
  const sizePills = document.querySelectorAll('.size-pill');
  sizePills.forEach(pill => {
    pill.addEventListener('click', () => {
      sizePills.forEach(p => {
        p.classList.remove('bg-primary', 'text-on-primary', 'shadow-sm');
        p.classList.add('bg-surface-container', 'text-on-surface');
      });
      pill.classList.remove('bg-surface-container', 'text-on-surface');
      pill.classList.add('bg-primary', 'text-on-primary', 'shadow-sm');
    });
  });

  // Size modal open / close
  const sizeModal = document.getElementById('size-modal');
  const openModalBtn = document.getElementById('open-size-guide');
  const closeModalBtn = document.getElementById('close-size-guide');

  if (openModalBtn && sizeModal) {
    openModalBtn.addEventListener('click', () => {
      sizeModal.classList.remove('hidden');
    });
  }

  if (closeModalBtn && sizeModal) {
    closeModalBtn.addEventListener('click', () => {
      sizeModal.classList.add('hidden');
    });
  }

  // Quick feedback on Add to Bag
  const addBtn = document.getElementById('add-to-bag-btn');
  if (addBtn) {
    addBtn.addEventListener('click', () => {
      const originalHTML = addBtn.innerHTML;
      addBtn.innerHTML = '<span class="material-symbols-outlined text-[19px]">check</span><span class="font-label-md text-label-md uppercase">Added!</span>';
      setTimeout(() => {
        addBtn.innerHTML = originalHTML;
      }, 1800);
    });
  }
</script></main><aside class="fixed bottom-6 right-4 z-40 pointer-events-auto pb-safe"><a class="flex items-center gap-2 bg-[#25D366] text-white px-4 py-2.5 rounded-full shadow-[0_8px_24px_-2px_rgba(37,211,102,0.35)] hover:bg-[#20ba59] active:scale-95 transition-all duration-200" href="https://wa.me/" rel="noopener noreferrer" target="_blank"><span class="material-symbols-outlined text-[20px]">chat</span><span class="font-body-md text-body-md font-semibold tracking-normal text-white">Concierge</span></a></aside></body></html>